def _retry_after(response: httpx.Response) -> float | None:
    """The delay a 429 or 503 response asks for, in seconds, if any."""
    header = response.headers.get("retry-after-ms")
    if header is not None:
        try:
            return float(header) / 1000
        except ValueError:
            pass
    header = response.headers.get("retry-after")
    if header is None:
        return None
    try:
        return float(header)
    except ValueError:
        pass
    try:
        date = email.utils.parsedate_to_datetime(header)
    except (TypeError, ValueError):
        return None
    return (date - _datetime.datetime.now(_datetime.timezone.utc)).total_seconds()


